// ═══════════════════════════════════════════════════
// CORE AI AGENT NODE — Request Validation & Enrichment
// ═══════════════════════════════════════════════════
const body = $input.first().json.body || $input.first().json;

// Validate required fields
const komoditas = body.komoditas || body.commodity || 'padi';
const modul     = body.modul || body.module || 'auto';

// Auto-detect module from intent keywords
const text = JSON.stringify(body).toLowerCase();
let detectedModul = modul;
if (modul === 'auto') {
  if (text.includes('rab') || text.includes('anggaran') || text.includes('biaya'))
    detectedModul = 'rab';
  else if (text.includes('monte') || text.includes('simulasi') || text.includes('iterasi'))
    detectedModul = 'monte_carlo';
  else if (text.includes('harga') || text.includes('pasar') || text.includes('ja') || text.includes('japan'))
    detectedModul = 'market';
  else if (text.includes('karbon') || text.includes('carbon') || text.includes('co2') || text.includes('emisi'))
    detectedModul = 'carbon';
  else if (text.includes('prediksi') || text.includes('forecast') || text.includes('yield'))
    detectedModul = 'forecast';
  else if (text.includes('pdf') || text.includes('laporan') || text.includes('report'))
    detectedModul = 'pdf';
  else
    detectedModul = 'pipeline';  // Default: full pipeline
}

// Enrich request with defaults
const enriched = {
  modul: detectedModul,
  komoditas: komoditas,
  luas_ha: parseFloat(body.luas_ha || 1.0),
  harga_jual_rp_kg: parseFloat(body.harga_jual_rp_kg || 4500),
  estimasi_yield_ton_ha: parseFloat(body.estimasi_yield_ton_ha || 6.0),
  curah_hujan_mm: parseFloat(body.curah_hujan_mm || 1500),
  ph_tanah: parseFloat(body.ph_tanah || 6.5),
  suhu_rata_c: parseFloat(body.suhu_rata_c || 27),
  npk_n: parseFloat(body.npk_n || 100),
  npk_p: parseFloat(body.npk_p || 60),
  npk_k: parseFloat(body.npk_k || 60),
  is_sawah: Boolean(body.is_sawah || false),
  carbon_sink_pohon: parseInt(body.carbon_sink_pohon || 0),
  n_iterations: parseInt(body.n_iterations || 10000),
  language: body.language || 'id',
  generate_pdf: body.generate_pdf !== false,
  include_ja_market: body.include_ja_market !== false,
  original_body: body,
  request_id: `adv_${Date.now()}`,
  timestamp: new Date().toISOString(),
};

return [{ json: enriched }];

// HTML Extract Node — Parse JA Market HTML
// Extract 入荷量 and price data from JA market pages
const rawHtml = $input.first().json.data || $input.first().json.body || '';
const commodity = $('🤖 Core AI Agent Node').item.json.komoditas;

// Try to extract price tables from HTML
let extractedData = {
  commodity: commodity,
  html_available: rawHtml.length > 100,
  prices_found: [],
  volumes_found: [],
  parse_method: 'regex',
};

if (typeof rawHtml === 'string' && rawHtml.includes('円')) {
  // Extract prices (円)
  const priceMatches = rawHtml.match(/(\d{2,5})円/g) || [];
  extractedData.prices_found = priceMatches
    .map(m => parseInt(m.replace('円', '')))
    .filter(p => p >= 50 && p <= 10000)
    .slice(0, 10);

  // Extract volumes (ton or kg)
  const volMatches = rawHtml.match(/(\d+(?:\.\d+)?)\s*(?:トン|ton)/gi) || [];
  extractedData.volumes_found = volMatches
    .map(m => parseFloat(m.replace(/[^\d.]/g, '')))
    .slice(0, 5);
}

// If scraping failed, pass through for API fallback
extractedData.use_api_fallback = extractedData.prices_found.length === 0;

return [{ json: {
  ...($('🤖 Core AI Agent Node').item.json),
  scraped_data: extractedData,
}}];

