// ═══════════════════════════════════════════════════
// RETURN NODE — Format final response ke UI
// ═══════════════════════════════════════════════════
const pdfResult    = $input.first().json;
const agentData    = $('🤖 Core AI Agent Node').item.json;
const langResult   = $('🌐 MCP Language Switch Node').item.json;

// Collect all module results
const modules_run = [];
const results = {};

// Try to get RAB result
try { results.rab = $('📊 RAB Processor Node').item.json; modules_run.push('rab'); } catch(e) {}
try { results.monte_carlo = $('🎲 Monte Carlo Node').item.json; modules_run.push('monte_carlo'); } catch(e) {}
try { results.ja_market = $('⚙️ Normalizer Node').item.json; modules_run.push('ja_market'); } catch(e) {}
try { results.carbon = $('🌿 Carbon Node').item.json; modules_run.push('carbon'); } catch(e) {}
try { results.forecast = $('📈 Forecasting Node').item.json; modules_run.push('forecast'); } catch(e) {}

// Build summary card
const summary = {
  komoditas: agentData.komoditas,
  luas_ha: agentData.luas_ha,
  modul_dijalankan: modules_run,
};

// Add key metrics from available results
if (results.rab?.data) {
  summary.roi_persen = results.rab.data.roi_persen;
  summary.keuntungan_rp = results.rab.data.keuntungan_bersih_rp;
  summary.bep_ton = results.rab.data.bep_ton;
}
if (results.monte_carlo?.data) {
  summary.prob_untung_pct = results.monte_carlo.data.prob_untung_persen;
  summary.roi_p50 = results.monte_carlo.data.roi_distribution?.p50;
}
if (results.ja_market?.data) {
  summary.harga_jepang_yen = results.ja_market.data.current_price_jpy;
  summary.peluang_ekspor = results.ja_market.data.export_opportunity;
}
if (results.carbon?.data) {
  summary.co2_total_ton = results.carbon.data.total_co2e_ton;
  summary.carbon_credit_usd = results.carbon.data.carbon_credit_usd;
}
if (results.forecast?.data) {
  summary.prediksi_yield = results.forecast.data.yield_forecast_ton_ha;
  summary.risk_level = results.forecast.data.risk?.level;
}

return [{
  json: {
    success: true,
    request_id: agentData.request_id,
    summary: summary,
    results: results,
    bilingual_labels: langResult?.data || {},
    pdf: pdfResult?.success ? {
      filename: pdfResult.filename,
      size_kb: pdfResult.size_kb,
      pdf_base64: pdfResult.pdf_base64,
    } : null,
    metadata: {
      engine: 'agrisensa-advanced-ai-engine-v1',
      workflow: 'WF-08',
      modules_count: modules_run.length,
      timestamp: new Date().toISOString(),
    }
  }
}];
